//! The public key the app trusts for update signatures.

/// The Ed25519 public key that verifies update signatures.
///
/// All zeros means "not set up": the app then refuses to update. The maintainer replaces it
/// with the constant printed by `cargo xtask keygen` (see docs/RELEASING.md). Never commit a
/// key that was not generated by that command.
pub const UPDATE_PUBLIC_KEY: [u8; 32] = [0; 32];

/// Whether `key` is a real key and not the all-zero placeholder.
pub fn is_configured(key: &[u8; 32]) -> bool {
    key.iter().any(|byte| *byte != 0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_placeholder_key_is_not_configured() {
        assert!(!is_configured(&[0; 32]));
        assert!(!is_configured(&UPDATE_PUBLIC_KEY));
    }

    #[test]
    fn any_other_key_is_configured() {
        let mut key = [0; 32];
        key[31] = 1;
        assert!(is_configured(&key));
    }
}
